     1→/**
     2→ * Main JavaScript for Rita Tomforde Artist Portfolio
     3→ * Handles mobile navigation toggle and smooth scrolling
     4→ */
     5→
     6→(function() {
     7→    'use strict';
     8→
     9→    /**
    10→     * Mobile Navigation Toggle
    11→     * Handles hamburger menu button interaction
    12→     */
    13→    function initMobileNav() {
    14→        const hamburger = document.querySelector('.hamburger');
    15→        const navMenu = document.querySelector('.nav-menu');
    16→
    17→        if (!hamburger || !navMenu) {
    18→            return;
    19→        }
    20→
    21→        // Create overlay element for mobile menu backdrop
    22→        let overlay = document.querySelector('.nav-overlay');
    23→        if (!overlay) {
    24→            overlay = document.createElement('div');
    25→            overlay.className = 'nav-overlay';
    26→            overlay.setAttribute('aria-hidden', 'true');
    27→            document.body.appendChild(overlay);
    28→        }
    29→
    30→        /**
    31→         * Toggle menu open/closed state
    32→         */
    33→        function toggleMenu() {
    34→            const isExpanded = hamburger.getAttribute('aria-expanded') === 'true';
    35→            const newState = !isExpanded;
    36→
    37→            hamburger.setAttribute('aria-expanded', String(newState));
    38→            navMenu.classList.toggle('is-active', newState);
    39→            overlay.classList.toggle('is-active', newState);
    40→
    41→            // Prevent body scroll when menu is open
    42→            document.body.style.overflow = newState ? 'hidden' : '';
    43→        }
    44→
    45→        /**
    46→         * Close the mobile menu
    47→         */
    48→        function closeMenu() {
    49→            hamburger.setAttribute('aria-expanded', 'false');
    50→            navMenu.classList.remove('is-active');
    51→            overlay.classList.remove('is-active');
    52→            document.body.style.overflow = '';
    53→        }
    54→
    55→        // Hamburger button click handler
    56→        hamburger.addEventListener('click', function(e) {
    57→            e.preventDefault();
    58→            toggleMenu();
    59→        });
    60→
    61→        // Close menu when clicking overlay
    62→        overlay.addEventListener('click', closeMenu);
    63→
    64→        // Close menu when clicking a nav link
    65→        const navLinks = navMenu.querySelectorAll('a');
    66→        navLinks.forEach(function(link) {
    67→            link.addEventListener('click', function() {
    68→                // Small delay to allow smooth scroll to start
    69→                setTimeout(closeMenu, 100);
    70→            });
    71→        });
    72→
    73→        // Close menu on escape key
    74→        document.addEventListener('keydown', function(e) {
    75→            if (e.key === 'Escape' && navMenu.classList.contains('is-active')) {
    76→                closeMenu();
    77→                hamburger.focus();
    78→            }
    79→        });
    80→
    81→        // Close menu on window resize above mobile breakpoint
    82→        let resizeTimer;
    83→        window.addEventListener('resize', function() {
    84→            clearTimeout(resizeTimer);
    85→            resizeTimer = setTimeout(function() {
    86→                if (window.innerWidth >= 768 && navMenu.classList.contains('is-active')) {
    87→                    closeMenu();
    88→                }
    89→            }, 100);
    90→        });
    91→    }
    92→
    93→    /**
    94→     * Smooth Scroll Enhancement
    95→     * Adds smooth scrolling behavior for anchor links
    96→     */
    97→    function initSmoothScroll() {
    98→        // Check if browser supports smooth scroll natively
    99→        if ('scrollBehavior' in document.documentElement.style) {
   100→            return; // Browser handles it via CSS scroll-behavior: smooth
   101→        }
   102→
   103→        // Fallback for older browsers
   104→        document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
   105→            anchor.addEventListener('click', function(e) {
   106→                const targetId = this.getAttribute('href');
   107→                if (targetId === '#') return;
   108→
   109→                const target = document.querySelector(targetId);
   110→                if (target) {
   111→                    e.preventDefault();
   112→                    target.scrollIntoView({
   113→                        behavior: 'smooth',
   114→                        block: 'start'
   115→                    });
   116→
   117→                    // Update URL hash without jumping
   118→                    if (history.pushState) {
   119→                        history.pushState(null, null, targetId);
   120→                    }
   121→                }
   122→            });
   123→        });
   124→    }
   125→
   126→    /**
   127→     * Initialize all functionality when DOM is ready
   128→     */
   129→    function init() {
   130→        initMobileNav();
   131→        initSmoothScroll();
   132→    }
   133→
   134→    // Run initialization when DOM is fully loaded
   135→    if (document.readyState === 'loading') {
   136→        document.addEventListener('DOMContentLoaded', init);
   137→    } else {
   138→        init();
   139→    }
   140→
   141→})();
